<canvas id="game" width="224" height="288"></canvas>
<script>
/*
  Galaga clone in one file.

  Internal resolution: 224 x 288, arcade-like 3:4 portrait.
  Everything is drawn procedurally or from pixel/rect sprite data.
  Audio is synthesized with Web Audio API.
*/

"use strict";

/* ------------------------------------------------------------------ */
/* Canvas and scaling                                                  */
/* ------------------------------------------------------------------ */

const W = 224;
const H = 288;
const canvas = document.getElementById("game");
const ctx = canvas.getContext("2d");
ctx.imageSmoothingEnabled = false;

function resizeCanvas() {
  const scale = Math.max(1, Math.floor(Math.min(window.innerWidth / W, window.innerHeight / H)));
  canvas.style.width = (W * scale) + "px";
  canvas.style.height = (H * scale) + "px";
}
window.addEventListener("resize", resizeCanvas);
resizeCanvas();

/* ------------------------------------------------------------------ */
/* Constants                                                           */
/* ------------------------------------------------------------------ */

const STEP = 1 / 60;

const COLORS = {
  ".": null,
  "W": "#ffffff",
  "R": "#ff4040",
  "Y": "#ffff40",
  "B": "#4080ff",
  "C": "#40ffff",
  "G": "#40ff40",
  "P": "#c040ff",
  "O": "#ff8040",
  "M": "#ff40ff",
  "D": "#808080"
};

/* ------------------------------------------------------------------ */
/* Pixel font                                                          */
/* ------------------------------------------------------------------ */

const FONT = {
  "A": [0x0e,0x11,0x11,0x1f,0x11,0x11,0x11],
  "B": [0x1e,0x11,0x11,0x1e,0x11,0x11,0x1e],
  "C": [0x0f,0x10,0x10,0x10,0x10,0x10,0x0f],
  "D": [0x1e,0x11,0x11,0x11,0x11,0x11,0x1e],
  "E": [0x1f,0x10,0x10,0x1e,0x10,0x10,0x1f],
  "F": [0x1f,0x10,0x10,0x1e,0x10,0x10,0x10],
  "G": [0x0f,0x10,0x10,0x17,0x11,0x11,0x0f],
  "H": [0x11,0x11,0x11,0x1f,0x11,0x11,0x11],
  "I": [0x0e,0x04,0x04,0x04,0x04,0x04,0x0e],
  "J": [0x07,0x02,0x02,0x02,0x02,0x12,0x0c],
  "K": [0x11,0x12,0x14,0x18,0x14,0x12,0x11],
  "L": [0x10,0x10,0x10,0x10,0x10,0x10,0x1f],
  "M": [0x11,0x11,0x11,0x15,0x15,0x11,0x11],
  "N": [0x11,0x19,0x19,0x15,0x13,0x11,0x11],
  "O": [0x0e,0x11,0x11,0x11,0x11,0x11,0x0e],
  "P": [0x1e,0x11,0x11,0x1e,0x10,0x10,0x10],
