}

function soundStageJingle() {
  const notes = [440, 550, 660, 880, 660, 880];
  for (let i = 0; i < notes.length; i++) {
    beep("square", notes[i], notes[i], 0.09, 0.10, i * 0.08);
  }
}

function soundChallengeBonus() {
  beep("square", 880, 880, 0.06, 0.11);
  beep("square", 1100, 1100, 0.06, 0.11, 0.06);
  beep("square", 1320, 1320, 0.10, 0.11, 0.12);
}

/* ------------------------------------------------------------------ */
/* Game state                                                          */
/* ------------------------------------------------------------------ */

let state = "title";
let paused = false;

let time = 0;
let frameCount = 0;

let score = 0;
let highScore = loadHighScore();
let lives = 2;              // reserve ships
let nextExtraLife = 20000;
let stage = 1;

let shotsFired = 0;
