let challengeMode = false;
let challengeWaveIndex = 0;
let challengeWaveSpawnTimer = 0;
let challengeWavesRemaining = [];
let challengeWaveDestroyed = [];
let challengeWaveBonusGiven = [];
let challengeBonus = 0;
let challengeHits = 0;
